export function Post(props) {
  return (
    <div id={props.id}>
      <img
        className={`h-56 z-10 w-screen ${props.imgCover ? "object-cover" : "object-scale-down"} border-t-4 border-b-4 -mb-4`}
        style={{backgroundColor: props.bgColor}}
        src={props.imgSrc} alt={props.imgAlt}/>
      <div className={"w-screen flex place-content-center sf-ui-reg text-lg"}>
        <div className={"w-2/5 border-l-4 border-r-4 p-4 mt-4"}>
          <div className={"sf-ui-bold text-6xl pb-2"}>
            {props.title}
          </div>
          <div>
            {props.date}
          </div>
          <div className={"pb-6 mt-2 border-t-4"}/>
          {props.children}
        </div>
      </div>
    </div>
  )
}

export function CodeBlock(props) {
  return (
    <div className={"border-4"}>
      <div className={"border-b-4 p-2"}>
        {props.lang}
      </div>
      <div className={"p-2 iosevka text-lg"}>
        {props.children}
      </div>
    </div>
  )
}
